UPDATE companies SET description='Galaxy Electronics Associates, Inc. was founded in 1988 in Laurel, Maryland, with the intention of providing quality printed circuit boards to the electronics industry. The company operates from a 22,000-square-foot facility in Laurel and has grown steadily over more than three decades.

The company manufactures a full range of printed circuit boards, including rigid, high-density interconnect (HDI), flex, rigid-flex, RF/microwave, and metal-core designs. Production capabilities cover single-sided through 14-layer multilayer boards with thicknesses from 0.002 to 0.200 inches, minimum line and space of 0.005 inches, and drilled holes down to 0.008 inches. Maximum panel size is 16 by 22 inches with copper weights up to 5 ounces. The shop supports prototype, quick-turn, and volume production runs, and offers design-for-manufacturability review as well as full PCB layout services with specialized RF and microwave expertise.

Galaxy Electronics serves original equipment manufacturers, engineers, and product teams across aerospace and defense, medical devices and healthcare, telecommunications and RF systems, automotive and EV electronics, and industrial automation and control. Its customer base spans the Mid-Atlantic region — Maryland, Washington D.C., Virginia, Pennsylvania, New York, and New Jersey — as well as national accounts.

The company emphasizes quality and customer service as its foundation, citing UL-approved processes, adherence to military and IPC specifications, and a commitment to on-time delivery. It also provides material selection guidance for substrates such as FR-4, PTFE, Rogers, Taconic, Arlon, and metal-core laminates to optimize signal integrity, thermal performance, and mechanical stability.', certifications=ARRAY['UL approved','IPC standards','Military specifications']::text[], profile='{"capabilities": ["Rigid PCB fabrication", "HDI PCB fabrication", "Flex PCB fabrication", "Rigid-flex PCB fabrication", "RF/microwave PCB fabrication", "Metal core PCB fabrication (aluminum, copper)", "Hybrid/mixed-material stackups", "Single-sided, double-sided, and multilayer (up to 14 layers)", "Controlled impedance fabrication", "High-frequency design", "Precision drilling (0.008\u2033 min)", "Fine line/space (0.005\u2033 min)", "Large format panels (16\u2033\u00d722\u2033 max)", "Heavy copper (up to 5 oz)", "Soldermask: SMOBC, LPI, dry film (multi-color)", "Silkscreen legend printing (white, black, yellow)", "Surface finishes: ENEPIG, ENIG, HASL, tin, soft gold, hard gold", "PCB design and layout", "RF/microwave design expertise", "Design for manufacturability (DFM) review", "Rapid prototype fabrication", "Low-to-high volume production", "In-process quality checks", "Final electrical test and inspection"], "industries": ["Aerospace and defense", "Medical devices and healthcare", "Telecommunications and RF systems", "Automotive and EV electronics", "Industrial automation and control"], "materials": ["FR-4", "FR-5", "Polyamide", "Rogers", "Taconic", "Arlon", "PTFE", "Low-loss RF materials", "Ceramic-filled substrates", "High-frequency substrates", "Metal core (aluminum)", "Metal core (copper)", "High-Tg laminates"], "equipment": [], "volume": "Prototype to high-volume production", "lead_time": "", "tolerances": "Minimum line/space 0.005\u2033, minimum drill 0.008\u2033, board thickness 0.002\u2033\u20130.200\u2033", "built_on": ["UL-approved manufacturing processes", "Materials and processes per military and IPC standards", "Fast turnaround for prototype and production builds", "Scalable production from prototype to high volume", "Engineering support for manufacturability (DFM) and PCB layout"], "facts_used": ["Founded in 1988 -> db", "Headquarters in Laurel, Maryland -> /", "22,000 sq.ft. facility -> /", "UL approved manufacturing -> /capabilities", "Materials and processes per military and IPC spec -> /capabilities", "Up to 14 layer multilayer PCBs -> /capabilities", "Minimum line/space 0.005\u2033 -> /capabilities", "Minimum drill 0.008\u2033 -> /capabilities", "Maximum panel size 16\u2033x22\u2033 -> /capabilities", "Copper weight up to 5 oz -> /capabilities", "Substrates: FR-4, FR-5, Polyamide, Rogers, Taconic, Arlon, PTFE, ceramic-filled, metal core -> /capabilities", "Surface finishes: ENEPIG, ENIG, HASL, tin, soft gold, hard gold -> /capabilities", "Soldermask: SMOBC, LPI, dry film multi-color -> /capabilities", "Silkscreen: white, black, yellow -> /capabilities", "PCB design and layout services -> /capabilities", "RF/microwave design expertise -> /capabilities", "DFM support -> /about", "Prototype to volume production -> /about", "Industries: aerospace and defense, medical devices, telecommunications, automotive/EV, industrial automation -> /about", "Quality control: incoming inspection, in-process checks, final electrical test, visual/dimensional verification -> /quality", "Fast turnaround and on-time delivery -> /quality", "Customer service focus -> /", "Over 35 years experience -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Galaxy Electronics is a trusted PCB manufacturer in the USA, specializing in high-quality printed circuit board fabrication", "founded_year": "1988", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership